package edu.pe.cibertec.saibm.usuario.infrastructure.config; import java.time.Clock; import org.springframework.context.annotation.*; import org.springframework.scheduling.annotation.EnableScheduling; import edu.pe.cibertec.saibm.usuario.application.port.in.*; import edu.pe.cibertec.saibm.usuario.application.port.out.*; import edu.pe.cibertec.saibm.usuario.application.usecase.UserService; @Configuration @EnableScheduling public class UserConfig {@Bean Clock userClock(){return Clock.systemUTC();}@Bean UserService userService(UserStorePort s,UserEventPublisher e,Clock c){return new UserService(s,e,c);}@Bean(name="users") @Primary UserUseCase users(UserService s){return new UserTransactionalFacade(s);}}
